$PageW=16.57; $PageH=7.95; $RefW=1657.0; $RefH=795.0
function VX([double]$x){$PageW*$x/$RefW}; function VY([double]$y){$PageH-$PageH*$y/$RefH}
function Cell($s,$n,$v){try{$s.CellsU($n).FormulaU=$v}catch{}}
function Style($s,$fill,$line='RGB(80,80,80)',$pt=.7,$round=0){if($fill-eq'none'){Cell $s FillPattern 0}else{Cell $s FillPattern 1;Cell $s FillForegnd $fill};if($line-eq'none'){Cell $s LinePattern 0}else{Cell $s LineColor $line;Cell $s LineWeight "$pt pt"};if($round){Cell $s Rounding "$(VX $round) in"}}
function Txt($s,$t,$sz=10,$col='RGB(20,20,20)',$bold=$false){$s.Text=$t;Cell $s 'Char.Font' 4;Cell $s 'Char.Size' "$sz pt";Cell $s 'Char.Color' $col;Cell $s 'Char.Style' $(if($bold){1}else{0});Cell $s 'Para.HorzAlign' 1;Cell $s VerticalAlign 1;foreach($m in 'TxtMarginLeft','TxtMarginRight','TxtMarginTop','TxtMarginBottom'){Cell $s $m '.5 pt'}}
function Rect($x,$y,$w,$h,$t='',$fill='none',$line='RGB(80,80,80)',$sz=10,$bold=$false,$pt=.7,$round=5){$s=$script:p.DrawRectangle((VX $x),(VY ($y+$h)),(VX ($x+$w)),(VY $y));Style $s $fill $line $pt $round;if($t){Txt $s $t $sz 'RGB(20,20,20)' $bold};$s}
function Text($x,$y,$w,$h,$t,$sz=10,$col='RGB(20,20,20)',$bold=$false){$s=Rect $x $y $w $h '' 'none' 'none' $sz $bold 0 0;Txt $s $t $sz $col $bold;$s}
function Line($x1,$y1,$x2,$y2,$col='RGB(25,25,25)',$pt=.7,$arrow=$false,$dash=1){$s=$script:p.DrawLine((VX $x1),(VY $y1),(VX $x2),(VY $y2));Cell $s LineColor $col;Cell $s LineWeight "$pt pt";Cell $s LinePattern $dash;if($arrow){Cell $s EndArrow 4};$s}
function Wave($x,$y,$w,$h,$hotX=-1,$hotW=0){Rect $x $y $w $h '' 'RGB(247,249,251)' 'RGB(185,190,195)' 1 $false .5 3|Out-Null;if($hotX-ge 0){Rect ($x+$hotX) ($y-3) $hotW ($h+6) '' 'RGB(239,250,232)' 'RGB(56,140,38)' 1 $false .7 0|Out-Null};for($i=8;$i-lt$w-5;$i+=10){$a=5+(($i*17)%([int]($h*.65)));$c=if($hotX-ge 0-and$i-ge$hotX-and$i-le($hotX+$hotW)){'RGB(45,130,35)'}else{'RGB(58,113,165)'};Line ($x+$i) ($y+$h/2-$a/2) ($x+$i) ($y+$h/2+$a/2) $c .65|Out-Null}}
function Encoder($x,$y){Rect $x $y 110 75 "Audio`nEncoder" 'RGB(226,241,253)' 'RGB(34,105,170)' 11 $true 1 0|Out-Null}
function Tokens($x,$y,$labels,$fill='RGB(245,239,252)',$line='RGB(128,79,162)',$w=48,$gap=8){for($i=0;$i-lt$labels.Count;$i++){Rect ($x+$i*($w+$gap)) $y $w 55 $labels[$i] $fill $line 9 $false .7 5|Out-Null}}
function Status($x,$y,$w,$t,$good=$false){$fill=if($good){'RGB(244,250,239)'}else{'RGB(255,243,240)'};$line=if($good){'RGB(75,143,45)'}else{'RGB(225,93,70)'};$col=if($good){'RGB(38,126,30)'}else{'RGB(220,35,25)'};Rect $x $y $w 48 '' $fill $line 1 $false .8 10|Out-Null;Text ($x+35) ($y+5) ($w-45) 38 $t 11 $col $true|Out-Null;Rect ($x+12) ($y+10) 27 27 $(if($good){'V'}else{'!'}) $line $line 10 $true .5 14|Out-Null}
function PanelBase($x,$w,$title,$sub){Rect $x 42 $w 742 '' 'RGB(255,255,255)' 'RGB(185,185,185)' 1 $false .7 12|Out-Null;Text ($x+15) 55 ($w-30) 28 $title 12 'RGB(15,15,15)' $true|Out-Null;Text ($x+15) 88 ($w-30) 24 $sub 11 'RGB(85,85,85)' $true|Out-Null;Text ($x+15) 123 230 23 'Speech utterance (frames)' 9 'RGB(16,70,145)' $true|Out-Null;Text ($x+$w-245) 123 205 23 'Target hotword' 9 'RGB(45,126,25)' $true|Out-Null;Wave ($x+16) 160 ($w-32) 75 ([int]($w*.59)) 72}
