$dir=Split-Path -Parent $VsdxPath;if(!(Test-Path $dir)){New-Item -ItemType Directory $dir|Out-Null}
if(!(Test-Path $VsdxPath)){$v=New-Object -ComObject Visio.Application;$v.Visible=$false;$d=$v.Documents.Add('');$d.SaveAs($VsdxPath);$d.Close();$v.Quit()}
$backup=Join-Path $dir ("intro.backup-"+(Get-Date -Format yyyyMMdd-HHmmss)+'.vsdx');Copy-Item $VsdxPath $backup
$vis=New-Object -ComObject Visio.Application;$vis.Visible=$false
try{$doc=$vis.Documents.Open($VsdxPath);$script:p=$doc.Pages.Item(1);$p.PageSheet.CellsU('PageWidth').FormulaU="$PageW in";$p.PageSheet.CellsU('PageHeight').FormulaU="$PageH in";while($p.Shapes.Count){$p.Shapes.Item(1).Delete()|Out-Null};DrawFigure;$doc.Save();Export-VisioPageFormats -Document $doc -Page $p -SourcePath $VsdxPath -Formats @('png','svg') -OutputDir $dir -OutputBaseName 'intro_rebuilt' -PreviewPath (Join-Path $dir 'intro_rebuilt.png');"BACKUP=$backup";"SHAPES=$($p.Shapes.Count)"}finally{if($doc){$doc.Close()};$vis.Quit()}
